function calculate_final_price( float $cost_net, array $cat_slugs ): array {

        $review_reasons = [];

        // 1. Kaina pagal kategorijos antkaini (cost_net be PVM)
        $calculated = $this->calculate( $cost_net, $cat_slugs );

        // 2. S70 apvalinimas
        $rounded = $this->apply_psychological_rounding( $calculated );

        // 3. Min marzos saugiklis (TIK review flag — kainos NEKEICIA).
        //    Su markup >= 25% si saliga praktiskai nesuveikia; lieka kaip apsauga.
        $min_margin = $cost_net * ( 1 + self::MIN_MARGIN_MARKUP ) * self::VAT;
        if ( $rounded < $min_margin - 0.001 ) {
            $review_reasons[] = 'price_below_25pct_margin';
        }

        return [
            'price'          => $rounded,
            'review_reasons' => $review_reasons,
        ];
    }

    public function get_markup_table(): array    { return $this->category_markups; }
    public function get_default_markup(): float   { return $this->default_markup; }
